package timodern;
import java.util.List;
import net.minecraftforge.common.ForgeConfigSpec;
public class InfusionConfig {
    public static final ForgeConfigSpec SPEC;
    public static final ForgeConfigSpec.ConfigValue<List<? extends String>> BLACKLIST;
    public static final java.util.Map<String,ForgeConfigSpec.BooleanValue> EFFECTS=new java.util.LinkedHashMap<>();
    public static final ForgeConfigSpec.IntValue TELEPORT_RADIUS,LUCRUM_RANGE,LUCRUM_INTERVAL,VOLATUS_RANGE,VOLATUS_INTERVAL;
    static {var b=new ForgeConfigSpec.Builder();BLACKLIST=b.comment("Registry IDs of blocks that cannot receive infusions; original default is bedrock.").comment("禁止接受注魔的方块注册 ID 列表；空列表不额外限制", "设置说明 / Setting: Block registry IDs that cannot receive infusion; empty adds no restriction", "初始值 / Default: " + String.valueOf(List.of("minecraft:bedrock")) + "; 列表允许为空 / An empty list is allowed", "修改后重启世界或服务器 / Restart the world/server after editing.").defineListAllowEmpty("blockBlacklist",List.of("minecraft:bedrock"),v->v instanceof String s&&net.minecraft.resources.ResourceLocation.tryParse(s)!=null);TELEPORT_RADIUS=b.comment("异域效果的传送半径，单位方块", "设置说明 / Setting: Alienis teleport radius in blocks", "初始值 / Default: " + String.valueOf(10) + "; 范围 / Range: " + String.valueOf(1) + ".." + String.valueOf(50), "修改后重启世界或服务器 / Restart the world/server after editing.").defineInRange("alienis.teleportRadius",10,1,50);LUCRUM_RANGE=b.comment("贪婪效果作用范围，单位方块", "设置说明 / Setting: Lucrum effect range in blocks", "初始值 / Default: " + String.valueOf(10) + "; 范围 / Range: " + String.valueOf(1) + ".." + String.valueOf(40), "修改后重启世界或服务器 / Restart the world/server after editing.").defineInRange("lucrum.range",10,1,40);LUCRUM_INTERVAL=b.comment("贪婪效果检查间隔，单位 tick", "设置说明 / Setting: Lucrum check interval in ticks", "初始值 / Default: " + String.valueOf(4) + "; 范围 / Range: " + String.valueOf(1) + ".." + String.valueOf(20), "修改后重启世界或服务器 / Restart the world/server after editing.").defineInRange("lucrum.interval",4,1,20);VOLATUS_RANGE=b.comment("飞行效果作用范围，单位方块", "设置说明 / Setting: Volatus effect range in blocks", "初始值 / Default: " + String.valueOf(10) + "; 范围 / Range: " + String.valueOf(1) + ".." + String.valueOf(100), "修改后重启世界或服务器 / Restart the world/server after editing.").defineInRange("volatus.range",10,1,100);VOLATUS_INTERVAL=b.comment("飞行效果检查间隔，单位 tick", "设置说明 / Setting: Volatus check interval in ticks", "初始值 / Default: " + String.valueOf(1) + "; 范围 / Range: " + String.valueOf(1) + ".." + String.valueOf(20), "修改后重启世界或服务器 / Restart the world/server after editing.").defineInRange("volatus.interval",1,1,20);b.push("effects");for(String effect:InfusionEffects.ALL.keySet())EFFECTS.put(effect,b.comment("启用 "+effect+" 原有方块注魔效果；初始 true，可选 true/false；重启世界。", "Enable the original "+effect+" block infusion effect; default true, true/false; restart the world.").define(effect,true));b.pop();SPEC=b.build();}
    public static int interval(InfusionEffects.Definition d){return d.aspect().equals("lucrum")?LUCRUM_INTERVAL.get():d.aspect().equals("volatus")?VOLATUS_INTERVAL.get():d.interval();}
    public static boolean banned(net.minecraft.world.level.block.Block block){return BLACKLIST.get().contains(net.minecraftforge.registries.ForgeRegistries.BLOCKS.getKey(block).toString());}
    public static boolean enabled(String aspect){var option=EFFECTS.get(InfusionEffects.local(aspect));return option!=null&&(!SPEC.isLoaded()||option.get());}
}
